questionvariables.text:
validate_ab(ex) := block([s, ca, cb], if not every(lambda([vv], member(vv, [a,b])), listofvars(ex)) then "Use only the vectors a and b." else (s: ev(expand(ex), simp), ca: ev(coeff(s,a), simp), cb: ev(coeff(s,b), simp), if ev(is(s - ca*a - cb*b = 0), simp) and ev(numberp(float(ca)) and numberp(float(cb)), simp) then "" else "Write your answer as a number times a plus a number times b, for example 3/5*a+2/5*b."));
texput(a,"\\mathbf{a}"); texput(b,"\\mathbf{b}");
/* Design: give a point on the line AB, graded by property: coefficients add to 1 and the coefficient of b, mu, is in the named range, where AR = mu AB. Ten positions: three beyond B, three beyond A, four between A and B. Source: original. */
plist: [[1,1000,2,3,1/2],[-1000,0,-1,-2,1/2],[0,1/2,1/3,1/4,2/3],[1/2,1,2/3,3/4,1/3],[2,1000,3,4,3/2],[1,2,3/2,5/4,3],[-1000,-1,-2,-3,-1/2],[-1,0,-1/2,-1/3,-2],[0,1/4,1/5,1/8,1/3],[3/4,1,4/5,7/8,2/3]];
ix: 1+rand(10);
lo: plist[ix][1]; hi: plist[ix][2]; ms: plist[ix][3]; mt: plist[ix][4]; mw: plist[ix][5];
samp: (1-ms)*a+ms*b;
alt: (1-mt)*a+mt*b;
wrongreg: (1-mw)*a+mw*b;

feedbackvariables.text:
s: expand(ans1); la: coeff(s,a); mu: coeff(s,b);
online: is(abs(la+mu-1) < 10^-9);
inreg: is(mu > lo and mu < hi);
